<?php require_once __DIR__ . '/_layout.php';$maps=['product_categories'=>'Categorias de produtos','publication_categories'=>'Categorias de publicações','blog_categories'=>'Categorias do blog'];$table=$_GET['table']??'publication_categories';if(!isset($maps[$table]))$table='publication_categories';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);if($_POST['action']==='save'){$name=trim($_POST['name']);$slug=trim($_POST['slug']);if($id)$pdo->prepare("UPDATE $table SET name=?,slug=?,sort_order=?,is_active=? WHERE id=?")->execute([$name,$slug,(int)$_POST['sort_order'],(int)$_POST['is_active'],$id]);else $pdo->prepare("INSERT INTO $table(name,slug,sort_order,is_active) VALUES(?,?,?,?)")->execute([$name,$slug,(int)$_POST['sort_order'],(int)$_POST['is_active']]);}if($_POST['action']==='delete'&&$id)$pdo->prepare("DELETE FROM $table WHERE id=?")->execute([$id]);header('Location:/admin/categories.php?table='.$table);exit;}admin_header('Categorias');?><div class="actions"><?php foreach($maps as $t=>$l):?><a class="button <?=$t===$table?'orange':'light'?>" href="?table=<?=$t?>"><?=h($l)?></a><?php endforeach;?></div><section class="card"><form class="grid" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save"><label>Nome<input name="name" required></label><label>Slug<input name="slug" required placeholder="nome-da-categoria"></label><label>Ordem<input name="sort_order" type="number" value="0"></label><label>Ativa<select name="is_active"><option value="1">Sim</option><option value="0">Não</option></select></label><div class="full"><button>Cadastrar categoria</button></div></form></section><section class="card table-wrap"><table><tbody><?php foreach($pdo->query("SELECT * FROM $table ORDER BY sort_order,name") as $r):?><tr><td><b><?=h($r['name'])?></b><br><small><?=h($r['slug'])?></small></td><td><?=$r['is_active']?'Ativa':'Inativa'?></td><td><form method="post" onsubmit="return confirm('Excluir esta categoria? Ela só deve ser removida se não estiver em uso.')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="button danger">Excluir</button></form></td></tr><?php endforeach;?></tbody></table></section><?php admin_footer();
